/// The single operation `Render` implements.
data object RenderOperation

/// Request for a side-effect passed from the Core to the Shell.
/// 
/// The `EffectId` links the `Request` with the corresponding call to [`Core::resolve`] to pass the data back
/// to the [`App::update`] function (wrapped in the event provided to the capability originating the effect).
data class Request(
    val id: UInt,
    val effect: org.viptv.core.types.Effect,
)

/// A batch of effect requests from the Core to the Shell, as serialised by
/// [`Bridge::update`] and [`Bridge::resolve`].
/// 
/// The wire format is identical to `Vec<Request<Eff>>` (the newtype is
/// `serde(transparent)`), so existing shell code that already deserialises
/// a `Vec<Request>` remains binary-compatible.
/// 
/// Registering this type with the type-generation system causes the code
/// generators to emit a `Requests` type (with a `value` field containing the
/// list) together with a top-level `bincodeDeserialize` / `BincodeDeserialize`
/// helper, replacing the hand-written extension files that were previously
/// appended by `add_extensions()`.
data class Requests(
    val value: List<org.viptv.core.types.Request>,
)

data class Session(
    val sessionId: String,
    val accountId: String,
    val profileId: String? = null,
    val accessToken: String,
    val refreshToken: String,
    val expiresIn: Double,
)

data class SourceFailure(
    val source: String,
    val code: String? = null,
    val message: String,
)

/// Safe source labels shared by native and web renderers, separate from source identity.
data class SourcePresentation(
    val title: String,
    val body: String,
    val providerKey: String,
    val providerLabel: String,
)

data class SourceProducerOutcome(
    val sourceId: String,
    val label: String,
    val errorCode: String? = null,
    val errorMessage: String? = null,
)

data class SourceRank(
    val rank: Double,
    val likely: Boolean,
    val best: Boolean,
)

/// One rank per input source and a stable display order; never a playback choice.
data class SourceRanks(
    val ranks: List<org.viptv.core.types.SourceRank>,
    val orderedIndices: List<UInt>,
)

data class SourcesPollState(
    val after: Double,
    val sources: List<org.viptv.core.types.MediaSource>,
    val polls: UInt,
    val errors: List<org.viptv.core.types.SourceFailure>? = null,
    val producers: List<org.viptv.core.types.SourceProducerOutcome>,
)

data class SourcesPollStep(
    val state: org.viptv.core.types.SourcesPollState,
    val sources: List<org.viptv.core.types.MediaSource>,
    val done: Boolean,
    val producers: List<org.viptv.core.types.SourceProducerOutcome>,
)

sealed interface StorageOperation {
    data object Load: StorageOperation

    data class Save(
        val value: String,
    ) : StorageOperation

    data object Clear: StorageOperation
}

sealed interface StorageResult {
    data class Ok(
        val value: String? = null,
    ) : StorageResult

    data class Err(
        val value: String,
    ) : StorageResult
}

data class UpNextGateDecision(
    val attemptedKey: String? = null,
    val resumeAwaitingKey: String? = null,
    val start: Boolean,
)

data class UpNextGateInput(
    val mediaKey: String,
    val attemptedKey: String? = null,
    val resumeAwaitingKey: String? = null,
    val ended: Boolean,
    val eligible: Boolean,
    val continuationBusy: Boolean,
    val blocked: Boolean,
)

data class UpNextPlaybackDecision(
    val attemptedKey: String? = null,
    val resumeAwaitingKey: String? = null,
)

data class UpNextPlaybackInput(
    val mediaKey: String,
    val previousKey: String? = null,
    val attemptedKey: String? = null,
    val resumeAwaitingKey: String? = null,
    val explicitResume: Boolean,
    val positionMillis: Long,
    val durationMillis: Long? = null,
)

data class ViewModel(
    val phase: org.viptv.core.types.Phase,
    val identity: org.viptv.core.types.Identity? = null,
    val selectedProfileId: String? = null,
    val error: String? = null,
    val errorStatus: UShort? = null,
)

data class VizioAppConfig(
    val appId: String,
    val nameSpace: UShort,
    val message: String? = null,
)

data class VizioControllerOutput(
    val kind: org.viptv.core.types.VizioControllerOutputKind,
    val requestId: UInt? = null,
    val request: org.viptv.core.types.VizioRequest? = null,
    val result: Map<String, org.viptv.core.types.JsonValue>? = null,
    val error: org.viptv.core.types.VizioFailure? = null,
    val credentialChanged: Boolean,
)

enum class VizioControllerOutputKind {
    REQUEST,
    COMPLETE,
    ERROR;
}

data class VizioDiscoveryCandidate(
    val host: String,
    val port: UShort,
)

data class VizioFailure(
    val kind: org.viptv.core.types.VizioFailureKind,
    val message: String,
    val retryable: Boolean,
    val protocolStatus: String? = null,
)

enum class VizioFailureKind {
    INVALIDCONFIG,
    INVALIDINPUT,
    AUTHENTICATION,
    INVALIDPARAMETER,
    ENDPOINTNOTFOUND,
    BUSY,
    TRANSPORT,
    INVALIDRESPONSE,
    HTTPSTATUS;
}

enum class VizioHttpMethod {
    GET,
    PUT;
}

data class VizioInputInfo(
    val cname: String,
    val name: String,
    val metaName: String,
    val current: Boolean,
    val hashValue: Long? = null,
)

data class VizioPairingChallenge(
    val challengeType: UShort,
    val token: ULong,
)

data class VizioPlatformSupport(
    val protocolAvailable: Boolean,
    val transport: org.viptv.core.types.VizioTransportSupport,
    val reason: String,
)

data class VizioProtocolResponse(
    val status: String,
    val detail: String,
    val raw: Map<String, org.viptv.core.types.JsonValue>,
)

enum class VizioRemoteAction {
    KEYPRESS,
    KEYDOWN,
    KEYUP;
}

data class VizioRemoteEvent(
    val codeSet: UShort,
    val code: UShort,
    val action: org.viptv.core.types.VizioRemoteAction,
)

enum class VizioRemoteKey {
    SEEK_FWD,
    SEEK_BACK,
    PAUSE,
    PLAY,
    DOWN,
    LEFT,
    OK,
    RIGHT,
    UP,
    BACK,
    SMARTCAST,
    CC_TOGGLE,
    INFO,
    MENU,
    HOME,
    VOL_DOWN,
    VOL_UP,
    MUTE_OFF,
    MUTE_ON,
    MUTE_TOGGLE,
    PIC_MODE,
    PIC_SIZE,
    INPUT_NEXT,
    CH_DOWN,
    CH_UP,
    CH_PREV,
    EXIT,
    POW_OFF,
    POW_ON,
    POW_TOGGLE;
}

data class VizioRequest(
    val method: org.viptv.core.types.VizioHttpMethod,
    val url: String,
    val headers: Map<String, String>,
    val body: Map<String, org.viptv.core.types.JsonValue>? = null,
    val timeoutMillis: ULong,
    val maxResponseBytes: ULong,
)

sealed interface VizioRequestResult {
    data class Ok(
        val value: org.viptv.core.types.VizioRequest,
    ) : VizioRequestResult

    data class Err(
        val value: org.viptv.core.types.VizioFailure,
    ) : VizioRequestResult
}

sealed interface VizioResponseResult {
    data class Ok(
        val value: org.viptv.core.types.VizioProtocolResponse,
    ) : VizioResponseResult

    data class Err(
        val value: org.viptv.core.types.VizioFailure,
    ) : VizioResponseResult
}

enum class VizioTransportSupport {
    NATIVE,
    UNAVAILABLE;
}
